<?php
declare(strict_types=1);
require_once __DIR__.'/config.php';

function e($value): string { return htmlspecialchars((string)$value, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8'); }
function text_slice(string $value, int $start, int $length): string { return function_exists('mb_substr') ? mb_substr($value, $start, $length, 'UTF-8') : substr($value, $start, $length); }
function text_length(string $value): int { return function_exists('mb_strlen') ? mb_strlen($value, 'UTF-8') : strlen($value); }
function start_session(): void { if (session_status() !== PHP_SESSION_ACTIVE && !session_start()) throw new RuntimeException('PHP session_start failed'); }
function request_is_https(): bool { return (!empty($_SERVER['HTTPS']) && $_SERVER['HTTPS'] !== 'off') || (PHP_SAPI !== 'cli' && getenv('LITEBBS_HTTPS') === '1'); }
function database_error_message(PDOException $error): string { $info=$error->errorInfo;$driverCode=(int)($info[1]??$error->getCode());return match($driverCode){1045,1698=>'数据库认证失败：请检查数据库用户名、密码，以及该用户是否允许从当前 Web 服务器连接。',1049=>'数据库不存在：请先创建填写的数据库，或更正数据库名称。',1044,1142,1143=>'数据库权限不足：该账户需要访问目标数据库并创建表、索引和初始数据。',default=>'数据库不可用：请检查数据库主机、端口、网络访问和服务状态。'}; }
function db(): PDO { static $pdo; if (!$pdo) { $c=load_config();$pdo=new PDO('mysql:host='.$c['host'].';port='.$c['port'].';dbname='.$c['name'].';charset=utf8mb4',$c['user'],$c['pass'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_EMULATE_PREPARES=>false,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]); } return $pdo; }
function database_host_is_valid(string $host): bool {
    $host=trim($host);
    if ($host==='' || strlen($host)>253 || preg_match('/[\x00-\x20\\\/]/',$host)) return false;
    if (strcasecmp($host,'localhost')===0) return true;
    if (filter_var($host,FILTER_VALIDATE_IP)) return true;
    if (!preg_match('/^(?=.{1,253}$)(?:[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\.)*[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?$/i',$host)) return false;
    return true;
}
function h(string $sql, array $args=[]): PDOStatement { $q=db()->prepare($sql);$q->execute($args);return $q; }
function redirect(string $to, int $status=303): void { header('Location: '.(preg_match('~^/(?!/)~',$to)?$to:'/'),true,$status);exit; }
function csrf(): string { start_session();if(empty($_SESSION['csrf']))$_SESSION['csrf']=bin2hex(random_bytes(32));return $_SESSION['csrf']; }
function confirmation_token(string $action,string $subject): string { start_session();$token=bin2hex(random_bytes(32));$_SESSION['confirmations'][$token]=['action'=>$action,'subject'=>$subject,'expires'=>time()+300];return $token; }
function require_confirmation(string $action,string $subject,string $token): void { start_session();$item=$_SESSION['confirmations'][$token]??null;unset($_SESSION['confirmations'][$token]);if(!is_array($item)||($item['expires']??0)<time()||!hash_equals((string)($item['action']??''),$action)||!hash_equals((string)($item['subject']??''),$subject))fail(403,'确认令牌无效或已过期'); }
function confirmation_page(string $title,string $message,string $action,array $fields,string $subject): void { $token=confirmation_token($action,$subject);$inputs='<input type="hidden" name="csrf" value="'.e(csrf()).'"><input type="hidden" name="confirm_token" value="'.e($token).'">';foreach($fields as $name=>$value)$inputs.='<input type="hidden" name="'.e((string)$name).'" value="'.e((string)$value).'">';page($title,'<section class="message"><h1>'.e($title).'</h1><p>'.e($message).'</p><form method="post">'.$inputs.'<button class="primary">确认执行</button></form></section>','',false,true); }
function setting(string $key, string $default=''): string { static $values=null,$version=null;$current=cache_version('settings');if($values===null||$version!==$current){$values=cached('settings:all:'.$current,30,static function(): array {$out=[];foreach(h('SELECT setting_key,setting_value FROM settings')->fetchAll() as $row)$out[$row['setting_key']]=$row['setting_value'];return $out;});$version=$current;}return (string)($values[$key]??$default); }
function install_token(): string { start_session();$token=time().'.'.bin2hex(random_bytes(16));$_SESSION['install_token']=$token;return $token; }
function verify_install_token(string $token): bool { start_session();return isset($_SESSION['install_token']) && hash_equals($_SESSION['install_token'],$token) && abs(time()-(int)explode('.',$token)[0])<3600; }
function request_url_parts(string $url): ?array { if($url===''||preg_match('/[\x00-\x20\\\\@]/',$url))return null;$parts=parse_url($url);if(!is_array($parts)||isset($parts['user'],$parts['pass'])||strtolower((string)($parts['scheme']??''))!=='https'||!isset($parts['host']))return null;$host=strtolower((string)$parts['host']);if($host===''||strlen($host)>253)return null;$port=(int)($parts['port']??443);if($port<1||$port>65535)return null;return ['scheme'=>'https','host'=>$host,'port'=>$port]; }
function same_https_origin(string $source,string $expected): bool { $actual=request_url_parts($source);$target=request_url_parts($expected);return $actual!==null&&$target!==null&&$actual===$target; }
function install_request_origin(): ?string { $host=(string)($_SERVER['HTTP_HOST']??'');if($host===''||preg_match('/[\x00-\x20\\\\\/\?\#@]/',$host))return null;return request_url_parts('https://'.$host)!==null?'https://'.$host:null; }
function require_post(): void { if(($_SERVER['REQUEST_METHOD']??'')!=='POST')fail(405,'只接受 POST 请求');if(!request_is_https())fail(403,'状态变更必须使用 HTTPS');$install=parse_url($_SERVER['REQUEST_URI']??'',PHP_URL_PATH)==='/install';if($install){if(!verify_install_token((string)($_POST['install_token']??'')))fail(403,'安装 nonce 无效');}elseif(!hash_equals(csrf(),(string)($_POST['csrf']??'')))fail(403,'CSRF token 无效');$source=(string)($_SERVER['HTTP_ORIGIN']??$_SERVER['HTTP_REFERER']??'');$expected=$install?install_request_origin():(string)(load_config()['url']??'');if($source===''||$expected===''||!same_https_origin($source,$expected))fail(403,'来源校验失败');if($install)unset($_SESSION['install_token']); }
function fail(int $status,string $message): void { http_response_code($status);page('请求失败','<section class="message"><h1>'.e($message).'</h1><a href="/">返回首页</a></section>'); }
function current_user(): ?array { static $loaded=false,$user=null;if($loaded)return $user;$loaded=true;if(!is_file(install_lock_file())||!is_file(config_file())||empty($_COOKIE[session_name()]))return null;start_session();$sid=(int)($_SESSION['sid']??0);$uid=(int)($_SESSION['uid']??0);$token=(string)($_SESSION['token']??'');if(!$sid||!$uid||!$token)return null;$user=h('SELECT u.id,u.username,u.email,u.role,u.points,u.locale,u.avatar_path,s.user_agent_hash,s.last_seen_at FROM sessions s JOIN users u ON u.id=s.user_id WHERE s.id=? AND s.user_id=? AND s.token_hash=? AND s.expires_at>UTC_TIMESTAMP(6) AND u.status="active"',[$sid,$uid,hash('sha256',$token)])->fetch()?:null;if(!$user){$_SESSION=[];return null;}$ua=hash('sha256',substr((string)($_SERVER['HTTP_USER_AGENT']??''),0,200));if(!hash_equals((string)$user['user_agent_hash'],$ua)){h('DELETE FROM sessions WHERE id=?',[$sid]);$_SESSION=[];return null;}if(strtotime((string)$user['last_seen_at'])<time()-300)h('UPDATE sessions SET last_seen_at=UTC_TIMESTAMP(6) WHERE id=?',[$sid]);unset($user['user_agent_hash'],$user['last_seen_at']);return $user; }
function login_user(int $id): void { start_session();session_regenerate_id(true);$token=bin2hex(random_bytes(32));$ip=(string)($_SERVER['REMOTE_ADDR']??'');$prefix=strpos($ip,':')!==false?substr($ip,0,strrpos($ip,':')):$ip;h('INSERT INTO sessions(user_id,token_hash,expires_at,last_seen_at,user_agent_hash,ip_prefix_hash) VALUES(?,?,DATE_ADD(UTC_TIMESTAMP(6),INTERVAL 30 DAY),UTC_TIMESTAMP(6),?,?)',[$id,hash('sha256',$token),hash('sha256',substr((string)($_SERVER['HTTP_USER_AGENT']??''),0,200)),hash('sha256',$prefix)]);$_SESSION=['uid'=>$id,'sid'=>(int)db()->lastInsertId(),'token'=>$token,'csrf'=>bin2hex(random_bytes(32))]; }
function admin(): array { $u=current_user();if(!$u)redirect('/login');if($u['role']!=='admin')fail(403,'无权访问');return $u; }
function enforce_post_interval(int $userId): void { $interval=(int)setting('post_interval','0');if($interval<=0)return;$last=h('SELECT GREATEST(COALESCE((SELECT MAX(created_at) FROM topics WHERE user_id=?),"1000-01-01"),COALESCE((SELECT MAX(created_at) FROM posts WHERE user_id=?),"1000-01-01"))',[$userId,$userId])->fetchColumn();if($last&&strtotime((string)$last)>time()-$interval)fail(429,'发帖间隔尚未结束，请稍后再试。'); }
function limit_action(string $action,int $max,int $seconds,string $identity): void { $bucket=hash('sha256',$action.'|'.$identity);h('INSERT INTO rate_limits(bucket,counter,reset_at) VALUES(?,1,DATE_ADD(UTC_TIMESTAMP(6),INTERVAL '.$seconds.' SECOND)) ON DUPLICATE KEY UPDATE counter=IF(reset_at<=UTC_TIMESTAMP(6),1,counter+1),reset_at=IF(reset_at<=UTC_TIMESTAMP(6),DATE_ADD(UTC_TIMESTAMP(6),INTERVAL '.$seconds.' SECOND),reset_at)',[$bucket]);if((int)h('SELECT counter FROM rate_limits WHERE bucket=?',[$bucket])->fetchColumn()>$max)fail(429,'操作过于频繁，请稍后再试'); }
function render_md(string $text): string { return nl2br(e($text),false); }
function form(string $action,string $title,string $fields): string { $token=$action==='/install'?'<input type="hidden" name="install_token" value="'.e(install_token()).'">':'<input type="hidden" name="csrf" value="'.e(csrf()).'">';return '<form class="form" method="post" action="'.e($action).'"><h1>'.e($title).'</h1>'.$token.$fields.'<button class="primary">保存</button></form>'; }
function input(string $name,string $label,string $type='text',string $attrs=''): string { return '<label>'.e($label).'<input name="'.e($name).'" type="'.e($type).'" '.$attrs.' required></label>'; }
function pagination(int $current, int $total): string { if($total<=1)return ''; $current=max(1,min($current,$total));$out='<nav class="pagination" aria-label="分页">';if($current>1)$out.='<a class="pagination-prev" href="?page='.($current-1).'">上一页</a>';$pages=[1];for($page=max(2,$current-2);$page<=min($total-1,$current+2);$page++)$pages[]=$page;if($total>1)$pages[]=$total;$pages=array_values(array_unique($pages));$previous=0;foreach($pages as$page){if($previous&&$page>$previous+1)$out.='<span class="pagination-gap">…</span>';$out.='<a'.($page===$current?' aria-current="page"':'').' href="?page='.$page.'">'.$page.'</a>';$previous=$page;}if($current<$total)$out.='<a class="pagination-next" href="?page='.($current+1).'">下一页</a>';return $out.'</nav>'; }
function audit(string $action,string $type,?int $id,array $meta=[]): void { $u=current_user();h('INSERT INTO audit_logs(actor_id,action,target_type,target_id,metadata_json,ip_prefix_hash,created_at) VALUES(?,?,?,?,?,?,UTC_TIMESTAMP(6))',[$u['id']??null,$action,$type,$id,json_encode($meta,JSON_UNESCAPED_UNICODE),hash('sha256',(string)($_SERVER['REMOTE_ADDR']??''))]); }
function permanently_delete_topic(int $id): void { $db=db();$db->beginTransaction();try{$topic=h('SELECT id FROM topics WHERE id=? FOR UPDATE',[$id])->fetch();if(!$topic){$db->rollBack();fail(404,'主题不存在或已删除');}$postIds=array_map('intval',array_column(h('SELECT id FROM posts WHERE topic_id=? FOR UPDATE',[$id])->fetchAll(),'id'));$where='(ref_type="topic" AND ref_id=?)';$args=[$id];if($postIds){$marks=implode(',',array_fill(0,count($postIds),'?'));$where.=' OR (ref_type="post" AND ref_id IN ('.$marks.'))';$args=array_merge($args,$postIds);}$deltas=h('SELECT user_id,SUM(delta) AS delta FROM point_ledger WHERE '.$where.' GROUP BY user_id FOR UPDATE',$args)->fetchAll();foreach($deltas as $delta)h('UPDATE users SET points=points-? WHERE id=?',[(int)$delta['delta'],(int)$delta['user_id']]);h('DELETE FROM point_ledger WHERE '.$where,$args);if($postIds)h('DELETE FROM post_revisions WHERE post_id IN ('.implode(',',array_fill(0,count($postIds),'?')).')',$postIds);h('DELETE FROM posts WHERE topic_id=?',[$id]);h('DELETE FROM topics WHERE id=?',[$id]);audit('topic.permanently_deleted','topic',$id);$db->commit();}catch(Throwable $e){if($db->inTransaction())$db->rollBack();throw $e;}invalidate('topics'); }
function moderate_topic(int $id,string $column,int $value,string $action): void { if($id<1||!in_array($column,['is_pinned','is_locked'],true)||!in_array($value,[0,1],true))fail(400,'操作无效');$statement=h('UPDATE topics SET '.$column.'=? WHERE id=?',[$value,$id]);if($statement->rowCount()===0&&!h('SELECT id FROM topics WHERE id=?',[$id])->fetch())fail(404,'主题不存在或已删除');audit('topic.'.$action,'topic',$id);invalidate('topics'); }
function cache_error(string $message): void { error_log('cache: '.$message); }
function write_cache(string $key,array $data): void { $dir=dirname(__DIR__).'/cache';if(!is_dir($dir)&&!@mkdir($dir,0700,true)){cache_error('cannot create cache directory');return;}$path=$dir.'/'.hash('sha256',$key).'.cache';try{$encoded=json_encode($data,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR);}catch(Throwable $error){cache_error('cannot encode cache value');return;}$tmp=$path.'.'.bin2hex(random_bytes(4)).'.tmp';if(@file_put_contents($tmp,$encoded,LOCK_EX)===false){cache_error('cannot write cache temporary file');return;}if(!@rename($tmp,$path)){if(is_file($path))@unlink($path);if(!@rename($tmp,$path)){@unlink($tmp);cache_error('cannot rename cache temporary file');}} }
function read_cache(string $key,int $ttl=300): ?array { $path=dirname(__DIR__).'/cache/'.hash('sha256',$key).'.cache';if(!is_file($path)||filemtime($path)<time()-$ttl)return null;$data=json_decode((string)@file_get_contents($path),true);return is_array($data)?$data:null; }
function cached(string $key,int $ttl,callable $load): array { $value=read_cache($key,$ttl);if($value!==null)return $value;$dir=dirname(__DIR__).'/cache';if(!is_dir($dir)&&!@mkdir($dir,0700,true)){cache_error('cannot create cache directory');return $load();}$path=$dir.'/'.hash('sha256',$key).'.cache';$lock=@fopen($path.'.lock','c');if(!$lock||!flock($lock,LOCK_EX)){if($lock)fclose($lock);cache_error('cannot lock cache file');return $load();}try{$value=read_cache($key,$ttl);if($value!==null)return $value;$value=$load();if(!is_array($value))throw new RuntimeException('cache loader must return an array');write_cache($key,$value);return $value;}finally{flock($lock,LOCK_UN);fclose($lock);} }
function cached_topic_count(string $scope,?int $categoryId=null): int { $key='topic-count:v1:'.$scope.':'.$categoryId.':'.cache_version('topics').':'.cache_version('categories');$values=cached($key,30,static function() use($categoryId): array {$sql=$categoryId===null?'SELECT COUNT(*) FROM topics t JOIN categories c ON c.id=t.category_id WHERE t.status="normal" AND c.is_visible=1':'SELECT COUNT(*) FROM topics WHERE category_id=? AND status="normal"';$count=$categoryId===null?h($sql)->fetchColumn():h($sql,[$categoryId])->fetchColumn();return [(int)$count];});return (int)($values[0]??0); }
function count_topic_view(int $id): void { $dir=dirname(__DIR__).'/cache/topic-views';if(!is_dir($dir)&&!@mkdir($dir,0700,true)){cache_error('cannot create topic view cache directory');return;}$path=$dir.'/'.$id.'.cache';$lock=@fopen($path.'.lock','c');if(!$lock){cache_error('cannot open topic view cache lock');return;}if(!flock($lock,LOCK_EX|LOCK_NB)){fclose($lock);return;}if((int)@file_get_contents($path)<time()-60){h('UPDATE topics SET view_count=view_count+1 WHERE id=?',[$id]);if(@file_put_contents($path,(string)time(),LOCK_EX)===false)cache_error('cannot write topic view cache');}flock($lock,LOCK_UN);fclose($lock); }
function cache_version(string $key): int { $path=dirname(__DIR__).'/cache/version-'.hash('sha256',$key);return is_file($path)?(int)file_get_contents($path):1; }
function invalidate(string $key): void { $path=dirname(__DIR__).'/cache/version-'.hash('sha256',$key);$lock=@fopen($path.'.lock','c');if(!$lock){cache_error('cannot open cache version lock');return;}if(!flock($lock,LOCK_EX)){cache_error('cannot lock cache version');fclose($lock);return;}$version=is_file($path)?(int)file_get_contents($path):1;if(@file_put_contents($path,(string)($version+1),LOCK_EX)===false)cache_error('cannot write cache version');flock($lock,LOCK_UN);fclose($lock); }
function slug(string $s): string { $lower=function_exists('mb_strtolower')?mb_strtolower($s,'UTF-8'):strtolower($s);$s=trim((string)preg_replace('/[^\pL\pN]+/u','-',$lower),'-');return $s?:'topic'; }
function admin_nav(): string { return '<nav class="adminnav"><a href="/admin">总览</a><a href="/admin/content">内容</a><a href="/admin/users">用户</a><a href="/admin/categories">分区</a><a href="/admin/themes">模板</a><a href="/admin/plugins">插件</a><a href="/admin/market">扩展审核</a><a href="/admin/audit">审计</a><a href="/admin/settings">设置</a><a href="/admin/extensions">程序更新</a></nav>'; }
function render_template(string $file, array $variables): void { extract($variables, EXTR_SKIP); include $file; }
function page(string $title,string $body,string $description='轻量、开放的社区讨论',bool $indexable=false,bool $isAdmin=false): void { $root=dirname(__DIR__);$installed=is_file(install_lock_file())&&is_file(config_file());$config=$installed?load_config():['site'=>'LiteBBS','theme'=>'default','url'=>''];$theme=(string)($config['theme']??'default');if(!preg_match('/^[a-z][a-z0-9_-]{1,31}$/',$theme))$theme='default';$themeDir=$root.'/templates/'.$theme;if(!$isAdmin&&!extension_theme_runtime_valid($themeDir,$theme)){error_log('active theme failed runtime validation: '.$theme);$theme='default';$themeDir=$root.'/templates/default';if(!extension_theme_runtime_valid($themeDir,'default'))throw new RuntimeException('默认模板校验失败');}$user=$installed?current_user():null;if($user||!$indexable)header('Cache-Control: private, no-store');$scheme=request_is_https()?'https':'http';$host=(string)($_SERVER['HTTP_HOST']??'localhost');$requestPath=parse_url($_SERVER['REQUEST_URI']??'/',PHP_URL_PATH)?:'/';$canonical=rtrim((string)($config['url']??($scheme.'://'.$host)),'/').$requestPath;$adminPage=$isAdmin||strpos($requestPath,'/admin')===0;$left='';if($installed&&!$adminPage){$version=cache_version('categories');$categories=cached('categories:nav:'.$version,60,static function(): array{return h('SELECT id,title FROM categories WHERE is_visible=1 ORDER BY position,id')->fetchAll();});foreach($categories as $category){$id=(int)$category['id'];$left.='<a class="nav-item'.($requestPath==='/c/'.$id?' active':'').'" href="/c/'.$id.'"><span>'.e($category['title']).'</span></a>';}}$variables=['title'=>$title,'body'=>$body,'description'=>$description,'indexable'=>$indexable,'canonical'=>$canonical,'requestPath'=>$requestPath,'c'=>['site'=>(string)($config['site']??'LiteBBS'),'url'=>(string)($config['url']??''),'theme'=>$theme,'locale'=>(string)($config['locale']??'zh-CN')],'isAdminPage'=>$adminPage,'isHomePage'=>$requestPath==='/','isTopicPage'=>preg_match('~^/t/\d+~',$requestPath)===1,'user'=>$user,'safe'=>$theme,'left'=>$left,'right'=>'','active'=>''];render_template($adminPage?$root.'/app/admin-layout.php':$themeDir.'/layout.php',$variables);exit; }
